-- Unpublished submission document slice. Root alone promotes/applies after review.
begin;
-- Extend precisely the two prior purpose checks; leave all integrity/FK guards intact.
do $$declare constraint_name text;matched integer:=0;begin
 for constraint_name in select conname from pg_constraint where conrelid='app.private_assets'::regclass and contype='c'and pg_get_constraintdef(oid)like'%purpose%'loop
  matched:=matched+1;execute format('alter table app.private_assets drop constraint %I',constraint_name);
 end loop;if matched<>2 then raise exception 'Asset purpose constraint shape changed'using errcode='22023';end if;
end$$;
alter table app.private_assets add column assessment_id uuid;
alter table app.private_assets add foreign key(school_id,assessment_id)references app.assessments(school_id,id);
alter table app.private_assets add check(purpose in('PERSONAL','COURSE_RESOURCE','SUBMISSION_WORK'));
alter table app.private_assets add check((purpose='PERSONAL'and course_id is null and assessment_id is null)or(purpose='COURSE_RESOURCE'and course_id is not null and assessment_id is null)or(purpose='SUBMISSION_WORK'and course_id is not null and assessment_id is not null and byte_size<=524288));
create or replace function internal.asset_purpose_immutable()returns trigger language plpgsql set search_path=''as $$begin if new.purpose is distinct from old.purpose or new.course_id is distinct from old.course_id or new.assessment_id is distinct from old.assessment_id then raise exception 'Asset purpose immutable'using errcode='55000';end if;return new;end$$;
alter table app.submissions add column response_kind text not null default 'TEXT'check(response_kind in('TEXT','FILE'));
alter table app.submissions add column asset_ids uuid[] not null default array[]::uuid[];
alter table app.submission_drafts add column response_kind text not null default 'TEXT'check(response_kind in('TEXT','FILE'));
alter table app.submission_drafts add column asset_ids uuid[] not null default array[]::uuid[];
do $$declare constraint_name text;matched integer:=0;begin for constraint_name in select conname from pg_constraint where conrelid='app.submissions'::regclass and contype='c'and pg_get_constraintdef(oid)like'%length(content)%'loop matched:=matched+1;execute format('alter table app.submissions drop constraint %I',constraint_name);end loop;if matched<>1 then raise exception 'Submission content constraint shape changed'using errcode='22023';end if;end$$;
alter table app.submissions add check(length(content)<=50000 and((response_kind='TEXT'and length(btrim(content))>0)or(response_kind='FILE'and content=''and cardinality(asset_ids)>0))and cardinality(asset_ids)<=5 and array_position(asset_ids,null)is null);
alter table app.submission_drafts add check(cardinality(asset_ids)<=5 and array_position(asset_ids,null)is null and(response_kind<>'FILE'or content=''));
create table app.submission_artifacts(school_id uuid not null,submission_id uuid not null,asset_id uuid not null,sequence integer not null check(sequence between 1 and 5),primary key(school_id,submission_id,asset_id),unique(school_id,submission_id,sequence),foreign key(school_id,submission_id)references app.submissions(school_id,id),foreign key(school_id,asset_id)references app.private_assets(school_id,id));
create function internal.submission_asset_selection(value jsonb)returns uuid[] language plpgsql immutable set search_path=''as $$declare chosen uuid[];begin
 if value is null or jsonb_typeof(value)<>'array'or jsonb_array_length(value)>5 or exists(select 1 from jsonb_array_elements(value)entry where jsonb_typeof(entry)<>'string')then raise exception 'Bounded document array required'using errcode='22023';end if;
 begin chosen:=array(select entry::uuid from jsonb_array_elements_text(value)entry);exception when invalid_text_representation then raise exception 'Document identity invalid'using errcode='22023';end;
 if cardinality(chosen)<>(select count(distinct selected.id)from unnest(chosen)selected(id))or array_position(chosen,null)is not null then raise exception 'Unique document selection required'using errcode='22023';end if;return chosen;
end$$;
create function internal.validate_submission_assets(target_assessment uuid,target_assets uuid[])returns void language plpgsql security definer set search_path=''as $$declare school uuid:="authorization".school_id();assessment app.assessments;selected_asset uuid;matched integer;begin
 perform internal.require_assessment_available(target_assessment);select a.*into assessment from app.assessments a where a.school_id=school and a.id=target_assessment;
 if assessment.submission_kind<>'TEXT'or target_assets is null or cardinality(target_assets)>5 or cardinality(target_assets)<>(select count(distinct selected.id)from unnest(target_assets)selected(id))or array_position(target_assets,null)is not null then raise exception 'Unique bounded text-work documents required'using errcode='22023';end if;
 -- Hold selected rows through manifest/draft commit so retirement cannot interleave.
 foreach selected_asset in array target_assets loop
  perform 1 from app.private_assets a where a.school_id=school and a.id=selected_asset and a.owner_id="authorization".actor_id()and a.created_by="authorization".actor_id()and a.purpose='SUBMISSION_WORK'and a.assessment_id=target_assessment and a.course_id=assessment.course_id and a.state='AVAILABLE'for share;
  get diagnostics matched=row_count;if matched<>1 then raise exception 'Verified own assessment document required'using errcode='42501';end if;
 end loop;
end$$;
create function internal.submission_artifact_manifest()returns trigger language plpgsql security definer set search_path=''as $$declare selected_asset uuid;ordinal integer:=0;begin
 if cardinality(new.asset_ids)>0 then if new.school_id is distinct from "authorization".school_id()or new.learner_id is distinct from "authorization".actor_id()then raise exception 'Own submission manifest required'using errcode='42501';end if;perform internal.validate_submission_assets(new.assessment_id,new.asset_ids);end if;
 foreach selected_asset in array new.asset_ids loop ordinal:=ordinal+1;insert into app.submission_artifacts(school_id,submission_id,asset_id,sequence)values(new.school_id,new.id,selected_asset,ordinal);end loop;return new;
end$$;
create trigger submission_artifact_manifest after insert on app.submissions for each row execute function internal.submission_artifact_manifest();
create function internal.submission_artifact_list(target_submission uuid)returns jsonb language sql stable security definer set search_path=''as $$select coalesce(jsonb_agg(jsonb_build_object('id',a.id,'name',a.name,'contentType',a.content_type,'byteSize',a.byte_size,'sha256',a.sha256,'state',a.state)order by m.sequence),'[]'::jsonb)from app.submission_artifacts m join app.private_assets a on a.school_id=m.school_id and a.id=m.asset_id where m.school_id="authorization".school_id()and m.submission_id=target_submission$$;
create function internal.submitted_work_allowed(target_submission uuid)returns boolean language plpgsql stable security definer set search_path=''as $$declare school uuid:="authorization".school_id();source app.submissions;begin
 select s.*into source from app.submissions s where s.school_id=school and s.id=target_submission;if not found or not"authorization".can_access_school(school)or not"authorization".has_entitlement(school,'assessment')then return false;end if;
 -- Historical read scope is deliberately distinct from current-source write scope.
 return("authorization".current_role(school)='student'and source.learner_id="authorization".actor_id()and"authorization".can_learn_course(school,"authorization".assessment_course(school,source.assessment_id)))or("authorization".current_role(school)in('admin','teacher')and"authorization".can_mark_submission(school,source.id));
end$$;
create function internal.read_submitted_work(target_submission uuid)returns jsonb language plpgsql security definer set search_path=''as $$declare source app.submissions;begin
 if not internal.submitted_work_allowed(target_submission)then raise exception 'Submitted work denied'using errcode='42501';end if;select s.*into source from app.submissions s where s.school_id="authorization".school_id()and s.id=target_submission;
 return jsonb_build_object('submissionId',source.id,'assessmentId',source.assessment_id,'learnerId',source.learner_id,'revision',source.revision,'responseKind',source.response_kind,'content',source.content,'artifacts',internal.submission_artifact_list(source.id));
end$$;
create function internal.read_submission_asset(target_assessment uuid,target_asset uuid)returns jsonb language plpgsql security definer set search_path=''as $$declare asset app.private_assets;begin
 perform internal.require_assessment_available(target_assessment);select a.*into asset from app.private_assets a join app.assessments assessment on assessment.school_id=a.school_id and assessment.id=a.assessment_id and assessment.course_id=a.course_id where a.school_id="authorization".school_id()and a.id=target_asset and a.purpose='SUBMISSION_WORK'and a.assessment_id=target_assessment and assessment.submission_kind='TEXT'and a.owner_id="authorization".actor_id()and a.created_by="authorization".actor_id();if not found or asset.state='RETIRED'then raise exception 'Own document unavailable'using errcode='42501';end if;
 return jsonb_build_object('id',asset.id,'ownerId',asset.owner_id,'name',asset.name,'contentType',asset.content_type,'byteSize',asset.byte_size,'sha256',asset.sha256,'state',asset.state,'objectPath',asset.object_path);
end$$;
create function internal.submission_document_command(command_name text,target_assessment uuid,target_asset uuid,payload jsonb,command_key text,fingerprint text,request_id text)returns jsonb language plpgsql security definer set search_path=''as $$declare school uuid:="authorization".school_id();actor uuid:="authorization".actor_id();assessment app.assessments;asset app.private_assets;reservation jsonb;rid uuid;result jsonb;event_key text;begin
 perform internal.require_context();select a.*into assessment from app.assessments a where a.school_id=school and a.id=target_assessment for share;
 if not found or not"authorization".has_entitlement(school,'assessment')or"authorization".current_role(school)<>'student'or not"authorization".can_learn_course(school,assessment.course_id)then raise exception 'Own academic document denied'using errcode='42501';end if;
 if assessment.submission_kind<>'TEXT'or command_name is null or command_name not in('stage','finalize','retire')or payload is null or jsonb_typeof(payload)<>'object'then raise exception 'Document command invalid'using errcode='22023';end if;
 if command_name<>'retire'then perform internal.require_assessment_available(target_assessment);end if;
 if command_name='stage'then
  if target_asset is not null or payload-array['name','contentType','byteSize','sha256']<>'{}'::jsonb or jsonb_typeof(payload->'name')is distinct from'string'or jsonb_typeof(payload->'contentType')is distinct from'string'or jsonb_typeof(payload->'byteSize')is distinct from'number'or jsonb_typeof(payload->'sha256')is distinct from'string'or payload->>'contentType'not in('text/plain','application/pdf','image/png','image/jpeg')or(payload->>'byteSize')!~'^[0-9]+$'or(payload->>'byteSize')::numeric not between 1 and 524288 or(payload->>'sha256')!~'^[a-f0-9]{64}$'then raise exception 'Document metadata invalid'using errcode='22023';end if;
 else
  select a.*into asset from app.private_assets a where a.school_id=school and a.id=target_asset and a.purpose='SUBMISSION_WORK'and a.assessment_id=target_assessment and a.course_id=assessment.course_id and a.owner_id=actor and a.created_by=actor for update;
  if not found or(command_name='finalize'and asset.state='RETIRED')then raise exception 'Own document unavailable'using errcode='42501';end if;
  if command_name='finalize'then if payload-array['sha256','byteSize']<>'{}'::jsonb or asset.sha256 is distinct from payload->>'sha256'or jsonb_typeof(payload->'byteSize')is distinct from'number'or asset.byte_size::numeric is distinct from(payload->>'byteSize')::numeric then raise exception 'Document integrity mismatch'using errcode='22023';end if;
  else if payload-array['reason','confirmRetirement']<>'{}'::jsonb or jsonb_typeof(payload->'reason')is distinct from'string'or length(btrim(payload->>'reason'))not between 1 and 1000 or payload->'confirmRetirement'is distinct from'true'::jsonb then raise exception 'Explicit document retirement required'using errcode='22023';end if;end if;
 end if;
 reservation:=internal.begin_command(command_key,'submission.document.'||command_name,fingerprint);
 if reservation->>'state'='COMPLETED'then
  if command_name='stage'then perform 1 from app.private_assets a where a.school_id=school and a.id=(reservation->'response'->>'id')::uuid and a.owner_id=actor and a.assessment_id=target_assessment and a.purpose='SUBMISSION_WORK'and a.state<>'RETIRED';if not found then raise exception 'Staged document no longer available'using errcode='42501';end if;end if;return reservation->'response';
 elsif reservation->>'state'<>'NEW'then raise exception 'Document command pending'using errcode='22023';end if;
 if command_name='stage'then rid:=gen_random_uuid();insert into app.private_assets(school_id,id,owner_id,created_by,name,content_type,byte_size,sha256,object_path,purpose,course_id,assessment_id)values(school,rid,actor,actor,payload->>'name',payload->>'contentType',(payload->>'byteSize')::integer,payload->>'sha256',school::text||'/submission/'||rid::text,'SUBMISSION_WORK',assessment.course_id,assessment.id);result:=jsonb_build_object('id',rid,'state','STAGED');
 else
  rid:=asset.id;update app.private_assets a set state=case when command_name='finalize'then'AVAILABLE'else'RETIRED'end,available_at=case when command_name='finalize'then coalesce(a.available_at,clock_timestamp())else a.available_at end,retired_at=case when command_name='retire'then coalesce(a.retired_at,clock_timestamp())else a.retired_at end where a.school_id=school and a.id=rid;
  result:=jsonb_build_object('id',asset.id,'name',asset.name,'contentType',asset.content_type,'byteSize',asset.byte_size,'sha256',asset.sha256,'state',case when command_name='finalize'then'AVAILABLE'else'RETIRED'end);
 end if;
 event_key:='submission-document:'||command_name||':'||rid::text;
 if not exists(select 1 from internal.outbox_events e where e.school_id=school and e.deduplication_key=event_key)then perform internal.append_audit('submission.document.'||command_name,'asset',rid,request_id,'succeeded',case when command_name='retire'then jsonb_build_object('reason',payload->>'reason')else'{}'::jsonb end);perform internal.enqueue_event('submission.document.changed','asset',rid,1,'{}',event_key);end if;
 perform internal.finish_command(command_key,'submission.document.'||command_name,fingerprint,result);return result;
end$$;
create function internal.submission_work_command(command_name text,target_assessment uuid,prior_submission uuid,payload jsonb,command_key text,fingerprint text,request_id text)returns jsonb language plpgsql security definer set search_path=''as $$declare school uuid:="authorization".school_id();actor uuid:="authorization".actor_id();assessment app.assessments;prior app.submissions;current_source app.current_submissions;returned app.submission_returns;draft app.submission_drafts;assets uuid[];rid uuid;revision_value integer;reservation jsonb;result jsonb;allowed_fields text[];begin
 perform internal.require_assessment_available(target_assessment);select a.*into assessment from app.assessments a where a.school_id=school and a.id=target_assessment;
 if assessment.submission_kind<>'TEXT'or command_name is null or command_name not in('draft','submit','resubmit')or payload is null or jsonb_typeof(payload)<>'object'then raise exception 'Text/file work command required'using errcode='22023';end if;
 allowed_fields:=case command_name when'draft'then array['responseKind','content','assetIds','expectedRevision']when'resubmit'then array['responseKind','content','assetIds','expectedRevision','returnId']else array['responseKind','content','assetIds']end;
 if payload-allowed_fields<>'{}'::jsonb or jsonb_typeof(payload->'responseKind')is distinct from'string'or jsonb_typeof(payload->'content')is distinct from'string'or payload->>'responseKind'not in('TEXT','FILE')or length(payload->>'content')>50000 then raise exception 'Explicit actual work required'using errcode='22023';end if;
 assets:=internal.submission_asset_selection(coalesce(payload->'assetIds','[]'::jsonb));perform internal.validate_submission_assets(target_assessment,assets);
 if(payload->>'responseKind'='FILE'and(payload->>'content'<>''or cardinality(assets)=0))or(payload->>'responseKind'='TEXT'and length(btrim(payload->>'content'))=0)then raise exception 'Actual response source required'using errcode='22023';end if;
 if(command_name='submit'and prior_submission is not null)or(command_name='draft'and prior_submission is not null)or(command_name='resubmit'and prior_submission is null)or(command_name in('draft','resubmit')and(jsonb_typeof(payload->'expectedRevision')is distinct from'number'or(payload->>'expectedRevision')!~'^[0-9]+$'))or(command_name='resubmit'and jsonb_typeof(payload->'returnId')is distinct from'string')then raise exception 'Work revision context invalid'using errcode='22023';end if;
 perform pg_advisory_xact_lock(hashtextextended(school::text||':submission:'||target_assessment::text||':'||actor::text,0));select c.*into current_source from app.current_submissions c where c.school_id=school and c.assessment_id=target_assessment and c.learner_id=actor for update;
 reservation:=internal.begin_command(command_key,'submission.work.'||command_name,fingerprint);if reservation->>'state'='COMPLETED'then return reservation->'response';elsif reservation->>'state'<>'NEW'then raise exception 'Work command pending'using errcode='22023';end if;
 if command_name='draft'then
  if current_source.submission_id is not null and current_source.state<>'RETURNED'then raise exception 'Draft source unavailable'using errcode='22023';end if;select d.*into draft from app.submission_drafts d where d.school_id=school and d.assessment_id=target_assessment and d.learner_id=actor for update;
  if(payload->>'expectedRevision')::numeric is distinct from coalesce(draft.revision,0)::numeric then raise exception 'Draft revision changed'using errcode='22023';end if;
  insert into app.submission_drafts(school_id,assessment_id,learner_id,content,revision,response_kind,asset_ids)values(school,target_assessment,actor,payload->>'content',1,payload->>'responseKind',assets)on conflict(school_id,assessment_id,learner_id)do update set content=excluded.content,response_kind=excluded.response_kind,asset_ids=excluded.asset_ids,revision=app.submission_drafts.revision+1,updated_at=clock_timestamp()returning id,revision into rid,revision_value;
 elsif command_name='submit'then
  if current_source.submission_id is not null then raise exception 'Initial work already submitted'using errcode='22023';end if;
  insert into app.submissions(school_id,assessment_id,learner_id,content,response_kind,asset_ids)values(school,target_assessment,actor,payload->>'content',payload->>'responseKind',assets)returning id,revision into rid,revision_value;
 else
  select s.*into prior from app.submissions s where s.school_id=school and s.id=prior_submission and s.assessment_id=target_assessment and s.learner_id=actor;select r.*into returned from app.submission_returns r where r.school_id=school and r.id=(payload->>'returnId')::uuid;
  if prior.id is null or current_source.submission_id is distinct from prior.id or current_source.state<>'RETURNED'or returned.id is null or returned.submission_id is distinct from prior.id or returned.learner_id is distinct from actor or returned.assessment_id is distinct from target_assessment or returned.source_revision is distinct from prior.revision or returned.created_at>clock_timestamp()or(payload->>'expectedRevision')::numeric is distinct from prior.revision::numeric then raise exception 'Current return source required'using errcode='22023';end if;
  insert into app.submissions(school_id,assessment_id,learner_id,content,response_kind,asset_ids,revision,status,previous_submission_id,return_id)values(school,target_assessment,actor,payload->>'content',payload->>'responseKind',assets,prior.revision+1,'RESUBMITTED',prior.id,returned.id)returning id,revision into rid,revision_value;
 end if;
 -- The receipt is bounded; the API rereads exact source in this transaction.
 result:=jsonb_build_object('id',rid,'assessmentId',target_assessment,'revision',revision_value,'status',case command_name when'draft'then'DRAFT'when'resubmit'then'RESUBMITTED'else'SUBMITTED'end);
 perform internal.append_audit('submission.work.'||command_name,case when command_name='draft'then'submission_draft'else'submission'end,rid,request_id,'succeeded',jsonb_build_object('revision',revision_value));
 perform internal.enqueue_event(case when command_name='resubmit'then'submission.resubmitted'else'submission.work.changed'end,case when command_name='draft'then'submission_draft'else'submission'end,rid,revision_value,'{}','submission-work:'||command_name||':'||rid::text||':'||revision_value::text);
 perform internal.finish_command(command_key,'submission.work.'||command_name,fingerprint,result);return result;
end$$;
create function internal.read_submission_work_draft(target_assessment uuid)returns jsonb language plpgsql security definer set search_path=''as $$declare draft app.submission_drafts;artifacts jsonb;begin
 perform internal.require_assessment_available(target_assessment);if not exists(select 1 from app.assessments a where a.school_id="authorization".school_id()and a.id=target_assessment and a.submission_kind='TEXT')then raise exception 'Text/file draft required'using errcode='22023';end if;
 select d.*into draft from app.submission_drafts d where d.school_id="authorization".school_id()and d.assessment_id=target_assessment and d.learner_id="authorization".actor_id();if not found then return jsonb_build_object('id',null,'assessmentId',target_assessment,'revision',0,'responseKind','TEXT','content','','artifacts','[]'::jsonb,'status','DRAFT');end if;
 select coalesce(jsonb_agg(jsonb_build_object('id',a.id,'name',a.name,'contentType',a.content_type,'byteSize',a.byte_size,'sha256',a.sha256,'state',a.state)order by selected.ordinal),'[]'::jsonb)into artifacts from unnest(draft.asset_ids)with ordinality selected(id,ordinal)join app.private_assets a on a.school_id=draft.school_id and a.id=selected.id;
 return jsonb_build_object('id',draft.id,'assessmentId',draft.assessment_id,'revision',draft.revision,'responseKind',draft.response_kind,'content',draft.content,'artifacts',artifacts,'status','DRAFT');
end$$;
create function internal.submission_artifact_delivery(target_submission uuid,target_asset uuid)returns jsonb language plpgsql security definer set search_path=''as $$declare asset app.private_assets;begin
 if not internal.submitted_work_allowed(target_submission)then raise exception 'Academic document denied'using errcode='42501';end if;
 select a.*into asset from app.submission_artifacts m join app.submissions s on s.school_id=m.school_id and s.id=m.submission_id join app.assessments assessment on assessment.school_id=s.school_id and assessment.id=s.assessment_id join app.private_assets a on a.school_id=m.school_id and a.id=m.asset_id where m.school_id="authorization".school_id()and m.submission_id=target_submission and m.asset_id=target_asset and a.owner_id=s.learner_id and a.assessment_id=s.assessment_id and a.course_id=assessment.course_id and a.purpose='SUBMISSION_WORK'and a.state='AVAILABLE';if not found then raise exception 'Submitted document unavailable'using errcode='42501';end if;
 return jsonb_build_object('id',asset.id,'ownerId',asset.owner_id,'name',asset.name,'contentType',asset.content_type,'byteSize',asset.byte_size,'sha256',asset.sha256,'state',asset.state,'objectPath',asset.object_path);
end$$;
alter table app.submission_artifacts enable row level security;alter table app.submission_artifacts force row level security;revoke all on app.submission_artifacts from public,anon,authenticated,service_role,cuevo_api,cuevo_worker;create trigger immutable_history before update or delete on app.submission_artifacts for each row execute function internal.academic_history_immutable();create trigger immutable_truncate before truncate on app.submission_artifacts for each statement execute function internal.academic_history_immutable();
revoke execute on function internal.submission_asset_selection(jsonb),internal.validate_submission_assets(uuid,uuid[]),internal.submission_artifact_manifest(),internal.submission_artifact_list(uuid),internal.submitted_work_allowed(uuid),internal.read_submitted_work(uuid),internal.read_submission_asset(uuid,uuid),internal.submission_document_command(text,uuid,uuid,jsonb,text,text,text),internal.submission_work_command(text,uuid,uuid,jsonb,text,text,text),internal.read_submission_work_draft(uuid),internal.submission_artifact_delivery(uuid,uuid)from public,anon,authenticated,service_role,cuevo_api,cuevo_worker;
grant execute on function internal.read_submitted_work(uuid),internal.read_submission_asset(uuid,uuid),internal.submission_document_command(text,uuid,uuid,jsonb,text,text,text),internal.submission_work_command(text,uuid,uuid,jsonb,text,text,text),internal.read_submission_work_draft(uuid),internal.submission_artifact_delivery(uuid,uuid)to cuevo_api;
-- Legacy text draft commands remain one active draft source and explicitly reset document mode.
do $$declare definition text;anchor text;begin
 definition:=pg_get_functiondef('internal.save_submission_draft(uuid,text,integer)'::regprocedure);anchor:='do update set content=excluded.content,revision=';if position(anchor in definition)=0 then raise exception 'Legacy text draft shape changed'using errcode='22023';end if;definition:=replace(definition,anchor,'do update set content=excluded.content,response_kind=''TEXT'',asset_ids=array[]::uuid[],revision=');execute definition;
end$$;
-- Add metadata to existing authorized projections with asserted source shapes.
do $$declare definition text;signature text;anchor text;begin
 foreach signature in array array['internal.read_submission_page(integer,uuid,uuid)','internal.read_own_assessment_submissions(uuid[])']loop
  definition:=pg_get_functiondef(signature::regprocedure);anchor:='''content'',s.content';if position(anchor in definition)=0 then raise exception 'Submission page shape changed: %',signature using errcode='22023';end if;
  definition:=replace(definition,anchor,anchor||',''responseKind'',s.response_kind,''artifactCount'',cardinality(s.asset_ids)');execute definition;
 end loop;
 definition:=pg_get_functiondef('internal.read_current_marking_page(integer,uuid)'::regprocedure);anchor:='''content'',source.content';if position(anchor in definition)=0 then raise exception 'Marking source shape changed'using errcode='22023';end if;definition:=replace(definition,anchor,anchor||',''responseKind'',source.response_kind,''artifactCount'',cardinality(source.asset_ids)');execute definition;
end$$;
-- Only document/stored-work receipts ACK here; resubmission continues through the existing observed-revision source processor.
do $$declare definition text;anchor text;begin
 definition:=pg_get_functiondef('internal.process_learner_event(uuid,uuid)'::regprocedure);anchor:='begin'||chr(10);if position(anchor in definition)=0 then raise exception 'Document dispatcher shape changed'using errcode='22023';end if;
 definition:=replace(definition,anchor,'begin'||chr(10)||' if exists(select 1 from internal.outbox_events event where event.id=target_event and event.type in(''submission.document.changed'',''submission.work.changed''))then select*into e from internal.outbox_events where id=target_event for update;if e.state<>''PROCESSING''or e.lease_token is distinct from current_lease or e.lease_until<=clock_timestamp()or not((e.type=''submission.document.changed''and e.entity_type=''asset''and e.version=1 and exists(select 1 from app.private_assets a where a.school_id=e.school_id and a.id=e.entity_id and a.purpose=''SUBMISSION_WORK''and a.owner_id=e.actor_id))or(e.type=''submission.work.changed''and((e.entity_type=''submission''and exists(select 1 from app.submissions s where s.school_id=e.school_id and s.id=e.entity_id and s.learner_id=e.actor_id and s.revision=e.version))or(e.entity_type=''submission_draft''and exists(select 1 from internal.audit_events audit where audit.school_id=e.school_id and audit.actor_id=e.actor_id and audit.entity_type=''submission_draft''and audit.entity_id=e.entity_id and audit.action=''submission.work.draft''and audit.metadata->''revision''=to_jsonb(e.version))))))then raise exception ''Document event source invalid''using errcode=''22023'';end if;insert into internal.processed_events(event_id,school_id)values(e.id,e.school_id)on conflict(event_id)do nothing;if internal.complete_outbox(e.id,current_lease)is distinct from true then raise exception ''Document event lease changed''using errcode=''22023'';end if;return jsonb_build_object(''status'',''ACKNOWLEDGED'');end if;'||chr(10));execute definition;
end$$;
create table app.portfolio_artifacts(school_id uuid not null,item_id uuid not null,revision_id uuid not null,asset_id uuid not null,sequence integer not null check(sequence between 1 and 5),primary key(school_id,revision_id,asset_id),unique(school_id,revision_id,sequence),foreign key(school_id,revision_id,item_id)references app.portfolio_revisions(school_id,id,item_id),foreign key(school_id,asset_id)references app.private_assets(school_id,id));
create function internal.freeze_portfolio_artifacts(target_item uuid,target_revision uuid,target_assets jsonb)returns void language plpgsql security definer set search_path=''as $$declare item app.portfolio_items;source jsonb;chosen uuid[];selected_asset uuid;ordinal integer:=0;matched integer;begin
 select i.*into item from app.portfolio_items i join app.portfolio_revisions r on r.school_id=i.school_id and r.item_id=i.id and r.id=target_revision where i.school_id="authorization".school_id()and i.id=target_item and i.learner_id="authorization".actor_id();if not found then raise exception 'Own exact portfolio revision required'using errcode='42501';end if;
 source:=internal.portfolio_source(item.source_model,item.evidence_id,false);
 if target_assets is null then select coalesce(array_agg(m.asset_id order by m.sequence),array[]::uuid[])into chosen from app.submission_artifacts m where m.school_id=item.school_id and m.submission_id=(source->>'submissionId')::uuid;else chosen:=internal.submission_asset_selection(target_assets);end if;
 if cardinality(chosen)=0 and exists(select 1 from app.submissions s where s.school_id=item.school_id and s.id=(source->>'submissionId')::uuid and s.response_kind='FILE')then raise exception 'File-only portfolio requires actual selected work'using errcode='22023';end if;
 foreach selected_asset in array chosen loop
  perform 1 from app.submission_artifacts m join app.submissions s on s.school_id=m.school_id and s.id=m.submission_id join app.assessments assessment on assessment.school_id=s.school_id and assessment.id=s.assessment_id join app.private_assets a on a.school_id=m.school_id and a.id=m.asset_id where m.school_id=item.school_id and m.submission_id=(source->>'submissionId')::uuid and m.asset_id=selected_asset and a.owner_id=item.learner_id and a.assessment_id=s.assessment_id and a.course_id=assessment.course_id and a.purpose='SUBMISSION_WORK'and a.state='AVAILABLE'for share of a;
  get diagnostics matched=row_count;if matched<>1 then raise exception 'Exact available submitted artifact required'using errcode='42501';end if;
  ordinal:=ordinal+1;insert into app.portfolio_artifacts(school_id,item_id,revision_id,asset_id,sequence)values(item.school_id,item.id,target_revision,selected_asset,ordinal);
 end loop;
end$$;
do $$declare definition text;anchor text;begin
 definition:=pg_get_functiondef('internal.portfolio_command(text,uuid,jsonb,text,text,text)'::regprocedure);anchor:='receipt:=jsonb_build_object(';if position(anchor in definition)=0 then raise exception 'Portfolio receipt shape changed'using errcode='22023';end if;definition:=replace(definition,anchor,'if command_name in(''create'',''reflection'')then perform internal.freeze_portfolio_artifacts(iid,rid,payload->''assetIds'');end if;'||chr(10)||' '||anchor);
 anchor:='perform internal.read_portfolio_source_work(iid,revision.id);';if position(anchor in definition)=0 then raise exception 'Portfolio review source shape changed'using errcode='22023';end if;definition:=replace(definition,anchor,anchor||'perform 1 from app.portfolio_artifacts selected join app.private_assets a on a.school_id=selected.school_id and a.id=selected.asset_id where selected.school_id=school and selected.item_id=iid and selected.revision_id=revision.id for share of a;if exists(select 1 from app.portfolio_artifacts selected join app.private_assets a on a.school_id=selected.school_id and a.id=selected.asset_id where selected.school_id=school and selected.item_id=iid and selected.revision_id=revision.id and a.state<>''AVAILABLE'')then raise exception ''Selected document unavailable for review''using errcode=''22023'';end if;');execute definition;
 definition:=pg_get_functiondef('internal.portfolio_source(text,uuid,boolean)'::regprocedure);anchor:='''submissionKind'',a.submission_kind';if position(anchor in definition)=0 then raise exception 'Portfolio source metadata changed'using errcode='22023';end if;definition:=replace(definition,anchor,anchor||',''responseKind'',(select s.response_kind from app.submissions s where s.school_id=r.school_id and s.id=r.submission_id)');execute definition;
 definition:=pg_get_functiondef('internal.read_portfolio_source_work(uuid,uuid)'::regprocedure);anchor:='''kind'',''TEXT''';if position(anchor in definition)=0 then raise exception 'Portfolio source kind changed'using errcode='22023';end if;definition:=replace(definition,anchor,'''kind'',submitted.response_kind');
 anchor:='''content'',submitted.content)';if position(anchor in definition)=0 then raise exception 'Portfolio answer projection changed'using errcode='22023';end if;definition:=replace(definition,anchor,'''content'',submitted.content,''artifacts'',(select coalesce(jsonb_agg(jsonb_build_object(''id'',a.id,''name'',a.name,''contentType'',a.content_type,''byteSize'',a.byte_size,''sha256'',a.sha256,''state'',a.state)order by selected.sequence),''[]''::jsonb)from app.portfolio_artifacts selected join app.private_assets a on a.school_id=selected.school_id and a.id=selected.asset_id where selected.school_id=school and selected.item_id=item.id and selected.revision_id=revision.id))');execute definition;
 definition:=pg_get_functiondef('internal.read_portfolio_page(integer,uuid,uuid,uuid)'::regprocedure);anchor:='''sourceWorkApproved'',row_item.source_review_confirmed';if position(anchor in definition)=0 then raise exception 'Portfolio review metadata changed'using errcode='22023';end if;definition:=replace(definition,anchor,anchor||',''artifactCount'',(select count(*)from app.portfolio_artifacts selected where selected.school_id=school and selected.item_id=row_item.id and selected.revision_id=row_item.revision_id)');execute definition;
end$$;
create function internal.portfolio_artifact_delivery(target_item uuid,target_revision uuid,target_asset uuid)returns jsonb language plpgsql security definer set search_path=''as $$declare work jsonb;asset app.private_assets;begin
 work:=internal.read_portfolio_source_work(target_item,target_revision);
 select a.*into asset from app.portfolio_artifacts selected join app.private_assets a on a.school_id=selected.school_id and a.id=selected.asset_id join app.submission_artifacts manifest on manifest.school_id=selected.school_id and manifest.asset_id=selected.asset_id and manifest.submission_id=(work->'source'->>'submissionId')::uuid where selected.school_id="authorization".school_id()and selected.item_id=target_item and selected.revision_id=target_revision and selected.asset_id=target_asset and a.owner_id=(work->>'learnerId')::uuid and a.assessment_id=(work->'source'->>'assessmentId')::uuid and a.purpose='SUBMISSION_WORK'and a.state='AVAILABLE';if not found then raise exception 'Selected portfolio artifact unavailable'using errcode='42501';end if;
 return jsonb_build_object('id',asset.id,'ownerId',asset.owner_id,'name',asset.name,'contentType',asset.content_type,'byteSize',asset.byte_size,'sha256',asset.sha256,'state',asset.state,'objectPath',asset.object_path);
end$$;
alter table app.portfolio_artifacts enable row level security;alter table app.portfolio_artifacts force row level security;revoke all on app.portfolio_artifacts from public,anon,authenticated,service_role,cuevo_api,cuevo_worker;create trigger immutable_history before update or delete on app.portfolio_artifacts for each row execute function internal.academic_history_immutable();create trigger immutable_truncate before truncate on app.portfolio_artifacts for each statement execute function internal.academic_history_immutable();
revoke execute on function internal.freeze_portfolio_artifacts(uuid,uuid,jsonb),internal.portfolio_artifact_delivery(uuid,uuid,uuid)from public,anon,authenticated,service_role,cuevo_api,cuevo_worker;grant execute on function internal.portfolio_artifact_delivery(uuid,uuid,uuid)to cuevo_api;
commit;




